import hashlib
import json
import re
from pathlib import Path

from pptx import Presentation

PRESENTATION = Path("03_Response_Escalation/HarborPoint_CrowdStrike_Executive_Status_Briefing.pptx")
BASELINE_FINGERPRINT = "1acf75db07b44310b2e4fab304a3f18a63720d05ea7c395732f4ec0bdcf526eb"


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _target_table(prs):
    for slide_number, slide in enumerate(prs.slides, 1):
        for shape in slide.shapes:
            if not getattr(shape, "has_table", False):
                continue
            table = shape.table
            headers = [_norm(cell.text) for cell in table.rows[0].cells]
            if "decision" not in headers or "owner" not in headers:
                continue
            decision_col = headers.index("decision")
            owner_col = headers.index("owner")
            for row_number in range(1, len(table.rows)):
                row = table.rows[row_number]
                if _norm(row.cells[decision_col].text) == "downtime control":
                    return slide_number, shape, row_number, decision_col, owner_col, row
    return None


def _fingerprint(prs):
    values = []
    target = _target_table(prs)
    target_key = None
    if target:
        slide_number, shape, row_number, _, owner_col, _ = target
        target_key = (slide_number, shape.name, row_number, owner_col)
    for slide_number, slide in enumerate(prs.slides, 1):
        for shape in slide.shapes:
            if getattr(shape, "has_table", False):
                for row_number, row in enumerate(shape.table.rows):
                    for col_number, cell in enumerate(row.cells):
                        text = cell.text
                        if target_key == (slide_number, shape.name, row_number, col_number):
                            text = "__TARGET_OWNER__"
                        values.append(["table", slide_number, shape.name, row_number, col_number, text])
            elif hasattr(shape, "text"):
                values.append(["text", slide_number, shape.name, shape.text])
    raw = json.dumps(values, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _load(ws):
    path = Path(ws) / PRESENTATION
    return path, Presentation(path)


def check_downtime_owner(ws):
    path, prs = _load(ws)
    target = _target_table(prs)
    if not target:
        return {"score": 0, "detail": "Could not locate the Downtime control decision row."}
    owner = target[-1].cells[target[4]].text
    owner_norm = _norm(owner)
    # Accept equivalent name/role orderings while requiring the governed Service Desk role.
    ok = ("elena ramirez" in owner_norm and
          "service desk incident commander" in owner_norm and
          "marcus hale" not in owner_norm)
    return {"score": int(ok), "detail": f"Owner cell is {owner!r}; expected Elena Ramirez as Service Desk Incident Commander."}


def check_decision_row_preserved(ws):
    _, prs = _load(ws)
    target = _target_table(prs)
    if not target:
        return {"score": 0, "detail": "Could not locate the Downtime control decision row."}
    row = target[-1]
    headers = [_norm(cell.text) for cell in target[1].table.rows[0].cells]
    fields = {headers[i]: row.cells[i].text for i in range(len(headers))}
    expected = {
        "requested action": "retain focused downtime readiness for the four impacted services until all transaction queues are reconciled",
        "due": "july 25 08 00",
        "consequence of delay": "incomplete reconciliation or unrecognized workflow gap",
    }
    actual = {key: _norm(fields.get(key)) for key in expected}
    ok = all(actual[key] == value for key, value in expected.items())
    return {"score": int(ok), "detail": f"Target row fields: {fields!r}"}


def check_presentation_integrity(ws):
    path, prs = _load(ws)
    ok = len(prs.slides) == 16 and _fingerprint(prs) == BASELINE_FINGERPRINT
    return {"score": int(ok), "detail": f"Slides={len(prs.slides)}, non-owner fingerprint matches baseline={_fingerprint(prs) == BASELINE_FINGERPRINT}."}
